unsigned int chip_probe(unsigned int mmu_enable)
{
	unsigned int chipid;

#ifdef CONFIG_ARCH_CKMMU_GX6605S
	chipid = 0x6605;
#else
	if (mmu_enable) {
		chipid = *((volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CHIP_ID));
		chipid = ((chipid >> 14) & 0xFFFF);
	} else {
		chipid = *((volatile unsigned int *)(CONFIG_BASE + CONFIG_CHIP_ID));
		chipid = ((chipid >> 14) & 0xFFFF);
	}
#endif

	return chipid;
}

