/**
 * spinand_read_id- Read SPI Nand ID
 *
 * Description:
 *    Read ID: read two ID bytes from the SPI Nand device
 */
static void spinand_read_id(void *id)
{
	struct spinand_cmd cmd;
	ssize_t retval;

	cmd.cmd = CMD_READ_ID;
	cmd.n_dummy = 1;
	cmd.n_rx = 2;
	cmd.rx_buf = id;

	cmd.n_addr = 0;
	cmd.n_tx = 0;

	spinand_cmd(&cmd);
}

static void spinand_get_features(u8 addr, u8 *features)
{
	struct spinand_cmd cmd;

	cmd.cmd = CMD_READ_REG;
	cmd.n_addr = 1;
	cmd.addr[0] = addr;
	cmd.n_rx = 1;
	cmd.rx_buf = features;

	cmd.n_dummy = 0;
	cmd.n_tx = 0;

	spinand_cmd(&cmd);
}

static void spinand_set_features(u8 addr, u8 *features)
{
	struct spinand_cmd cmd;

	cmd.cmd = CMD_WRITE_REG;
	cmd.n_addr = 1;
	cmd.addr[0] = addr;
	cmd.n_tx = 1;
	cmd.tx_buf = features;

	cmd.n_rx = 0;
	cmd.n_dummy = 0;

	spinand_cmd(&cmd);
}

static int spinand_enable_ecc(void)
{
	u8 features = 0, addr = 0;
	if ((spinand_id == 0xF20B) ||                        /* XT26G02BWSUGA  */  \
			(spinand_id == 0xA1CD) ||            /* FS35ND01G-D1F1 */  \
			(spinand_id == 0xB1CD) ||            /* FS35ND01G-S1F1 */
			(spinand_id == 0xF1A1))              /* TX25G01 */ {
		addr = REG_ECC;
	} else {
		addr = REG_OTP;
	}
	spinand_get_features(addr, &features);

	if ((features & REG_ECC_MASK) == REG_ECC_MASK) {
		return 0;
	}
	else {
		features |= REG_ECC_MASK;
		/* Dosilicon不能写OTP_PRT, 否则不能program */
		features &= ~OTP_PRT;
		spinand_set_features(addr, &features);
		return 1;
	}
}

static void spinand_read_page_to_cache(u32 page_id)
{
	struct spinand_cmd cmd;
	u32 row;

	row = page_id;

	cmd.cmd = CMD_READ;
	cmd.n_addr = 3;
	cmd.addr[0] = (u8)((row&0xff0000)>>16);
	cmd.addr[1] = (u8)((row&0xff00)>>8);
	cmd.addr[2] = (u8)(row&0x00ff);

	cmd.n_rx = 0;
	cmd.n_dummy = 0;
	cmd.n_tx = 0;

	spinand_cmd(&cmd);
}

static void spinand_read_status(u8 *status)
{
	struct spinand_cmd cmd;

	cmd.cmd = CMD_READ_REG;
	cmd.n_addr = 1;
	cmd.addr[0] = REG_STATUS;
	cmd.n_rx = 1;
	cmd.rx_buf = status;

	cmd.n_dummy = 0;
	cmd.n_tx = 0;

	spinand_cmd(&cmd);
}

static void spinand_wait_ready(void)
{
	u8 status = 0;

	while (1) {
		spinand_read_status(&status);

		if ((status & STATUS_OIP_MASK) == STATUS_READY)
			break;
	}
}

static void spinand_read_from_cache(u16 byte_id, u16 len, u8* rbuf)
{
	struct spinand_cmd cmd;
	u16 column;

	column = byte_id;

	cmd.cmd = CMD_READ_RDM;
	cmd.n_addr = 2;
	cmd.addr[0] = (u8)((column&0xff00)>>8);
	cmd.addr[1] = (u8)(column&0x00ff);
	cmd.n_dummy = 1;
	cmd.n_rx = len;
	cmd.rx_buf = rbuf;

	cmd.n_tx = 0;

	if(spinand_id == 0x68B4)  // GD5F4GM5UFY 4K pagesize
		spinand_cmd_for_4k_page(&cmd);
	else
		spinand_cmd(&cmd);
}

#define PAGES_PER_BLOCK            64
static int snand_read_page(u32 page_id, u16 offset, u16 len, u8 *rbuf)
{
	u8 status = 0;

	/* DS35Q2GA, F50L2G41XA, ZD35Q2GA只有一个die,每个die有两个plane.
	   当block number为奇数,选择另外一个plane. */
	if ((spinand_id == 0x72e5) || (spinand_id == 0xf2e5) || (spinand_id == 0x242c) ||
			(spinand_id == 0x72ba)) {
		if((page_id / PAGES_PER_BLOCK) % 2)
			offset |= (0x1 << 12);
	}

	spinand_read_page_to_cache(page_id);
	while (1) {
		spinand_read_status(&status);

		if ((status & STATUS_OIP_MASK) == STATUS_READY) {
			break;
		}
	}
	spinand_read_from_cache(offset, len, rbuf);
	return 0;
}

static void spinand_reset(void)
{
	struct spinand_cmd cmd;

	cmd.cmd = CMD_RESET;
	cmd.n_addr = 0;
	cmd.n_dummy = 0;
	cmd.n_rx = 0;
	cmd.rx_buf = 0;
	cmd.n_tx = 0;

	spinand_cmd(&cmd);
}

static int snand_init(void)
{
	int i;
	uint32_t* nand_bbt;
	uint32_t bbt_size;
	uint32_t crc_offs;
	uint32_t crc;
#if defined(CONFIG_ENABLE_DWSPI)
	uint32_t val;
#endif

	spi_init();
#ifdef CONFIG_ENABLE_DWSPI
	spl_spi_init(1, 0, 100000000, 0x00);
#endif

#ifdef CONFIG_ARCH_ARM_CANOPUS
#ifdef CONFIG_QFN88
		/* 切换到DW SPI:QFN88(GX6631SH1D) */
		val = readl(0x89400458);
		val &= ~(7 << 24);
		val |= 2 << 24;
		writel(val, 0x89400458);

		val = readl(0x8940045C);
		val &= ~(7 << 0 | 7 << 8 | 7 << 16 | 7 << 24);
		val |= 2 | 2 << 8 | 2 << 16 | 2 << 24;
		writel(val, 0x8940045C);

		val = readl(0x89400460);
		val &= ~(7 << 0);
		val |= 2 << 0;
		writel(val, 0x89400460);
#endif

#ifdef CONFIG_LQFP156
		/* 切换到DW SPI */
		val = readl(0x89400410);
		val &= ~(7 << 8 | 7 << 16 | 7 << 24);
		val |= 4 << 8 | 4 << 16 | 4 << 24;
		writel(val, 0x89400410);

		val = readl(0x89400414);
		val &= ~(7 << 0 | 7 << 8 | 7 << 16);
		val |= 4 << 0 | 4 << 8 | 4 << 16;
		writel(val, 0x89400414);
#endif

#ifdef CONFIG_BGA336
		val = readl(0x80403FFC);
		if (((val>>4) & 0xf) == 0x3) {
			val = readl(0x89400410);
			val &= ~(7 << 8 | 7 << 16 | 7 << 24);
			val |= 4 << 8 | 4 << 16 | 4 << 24;
			writel(val, 0x89400410);

			val = readl(0x89400414);
			val &= ~(7 << 0 | 7 << 8 | 7 << 16);
			val |= 4 << 0 | 4 << 8 | 4 << 16;
			writel(val, 0x89400414);
		} else {
			/* 切换到另一路 */
			val = readl(0x89400458);
			val &= ~(7 << 24);
			val |= 2 << 24;
			writel(val, 0x89400458);

			val = readl(0x8940045C);
			val &= ~(7 << 0 | 7 << 8 | 7 << 16 | 7 << 24);
			val |= 2 | 2 << 8 | 2 << 16 | 2 << 24;
			writel(val, 0x8940045C);

			val = readl(0x89400460);
			val &= ~(7 << 0);
			val |= 2 << 0;
			writel(val, 0x89400460);
		}
#endif
#endif /* CONFIG_ARCH_ARM_CANOPUS */

	spinand_wait_ready();

	for (i = 0; i < 100; i++) {

		spinand_read_id(&spinand_id);

		if ((spinand_id != 0xFFFF) && (spinand_id != 0x00))
			break;
	}

	spinand_enable_ecc();
	spinand_wait_ready();

	/* GD5F4GM5UFY 4K pagesize */
	if (spinand_id == 0x68B4 || spinand_id == 0xD4C9 || spinand_id == 0x130B) {
		p_snand_info = &nand_info[2];
	}

	bbt_ready = false;
	nand_bbt = (uint32_t*)TEMPORARY_BUF_BBT;

	for (i = 0; i < sizeof(nand_bbt_search) / sizeof(uint16_t); i++) {
		snand_read_page((uint32_t)nand_bbt_search[i] * 64, 0, 2048, (uint8_t*)nand_bbt);

		/* bbt mark: "Bbt0" OR "1tbB" */
		if ((nand_bbt[0] == 0x30746242) || (nand_bbt[0] == 0x42627431)) {
			bbt_size = (nand_bbt[1] >> 16) & 0x00ffff;
			if (bbt_size > 1024) {
				continue;
			}

			crc_offs = bbt_size + 8;
			crc = bbt_crc32((uint8_t*)nand_bbt, crc_offs);
			if (crc == nand_bbt[crc_offs/4]) {
				bbt_ready = true;
				break;
			}
		}
	}

	return 0;
}

static int snand_read_ops(ssize_t from, struct mtd_oob_ops *ops)
{
	assert_param(ops, -1);
	struct spi_nand_info *info = p_snand_info;
	int page_id, page_offset = 0;
	int count = 0;
	int main_left, main_ok = 0, main_offset = 0;
	int size, retval;

	page_id = from >> info->page_shift;
	page_offset = from & info->page_mask;
	main_left = ops->len;
	main_offset = page_offset;

	while (main_left){
		size = min(main_left, info->page_main_size - main_offset);
		retval = snand_read_page(page_id + count, main_offset, \
					size, ops->datbuf + main_ok);

		if (retval < 0) {
			//printf("snand_read_ops: fail, page=%d!\n", page_id);
			return -1;
		}

		main_ok += size;
		main_left -= size;
		main_offset = 0;
		count++;
	}

	ops->retlen = main_ok;

	return main_ok;
}

static int snand_block_isbad(u32 ofs)
{
	struct spi_nand_info *info = p_snand_info;
	uint32_t* nand_bbt = (uint32_t*)TEMPORARY_BUF_BBT;
	uint32_t block_id;

	u8 is_bad = 0x00;
	u32 page_id = (ofs >> info->block_shift) * info->page_num_per_block;
	block_id = page_id / 64;

	if (bbt_ready == true) {
		if (((nand_bbt[2+block_id/16] >> ((block_id % 16) << 1)) & 0x03)\
				!= 0x03)
			return 1;
		else
			return 0;
	}

	snand_read_page(page_id, info->page_main_size, 1, &is_bad);

	return is_bad == 0XFF ? 0 : 1;
}

static int snand_read_skip_bad(ssize_t offset, void *buf, uint32_t len)
{
	struct spi_nand_info *info = p_snand_info;
	uint32_t blk_sz    = info->block_main_size;
	ssize_t  read_left = len;

	if(len == 0)
		return 0;

	assert_param(offset + len <= info->usable_size, -1);

	uint8_t *pbuf = buf;
	struct   mtd_oob_ops ops;

	while(read_left > 0){
		ssize_t blk_ofs = offset & info->block_mask;
		/* skip bad block */
		if(snand_block_isbad(offset & ~info->block_mask)){
			offset += blk_sz - blk_ofs;
			continue;
		}

		ops.datbuf = pbuf;
		ops.len    = min(read_left, blk_sz-blk_ofs);

		if(snand_read_ops(offset, &ops) < 0)
			return -1;

		pbuf      += ops.retlen;
		offset    += ops.retlen;
		read_left -= ops.retlen;
	}

	return pbuf-(uint8_t*)buf;
}

static int snand_read(uint32_t offset, uint8_t *dest, uint32_t len)
{
	int ret;

	ret = snand_read_skip_bad(offset, dest, len);
	if (ret < 0)
		return -1;

	return 0;
}

static int copy_from_snflash(unsigned int addr, unsigned int len, unsigned char *buf)
{
	snand_read(addr, buf, len);
	return len;
}
