#endif
static int n_flash_do_read_page(uint32_t page,uint32_t *buf)
{

#ifdef CONFIG_ARCH_ARM_CANOPUS
#define NAND_DMA_ENABLE 1

	unsigned int reg_val, bkpt_continue;
	int end_page;
	uint32_t page_size = n_flash_pagesize;
	uint32_t ecc_strength = 0, ecc_enable = 1;

	do {
		reg_val = NAND_READ_REG(INT_STATUS);
	} while(!(reg_val & 0x01));
	/* disable NAND Controller */
	reg_val = NAND_READ_REG(ENABLE_STATUS);
	NAND_WRITE_REG(reg_val & (~0x01), ENABLE_STATUS);
	NAND_WRITE_REG((1<<24) | (1<< 20), INT_ENABLE);
	NAND_WRITE_REG(0, BKPT_ENABLE);

	if(n_flash_ecc_buildin == 1) {
		nandflash_noecc();
		ecc_strength = 0;
		ecc_enable = 0;
	}else {
		ecc_enable = 1;
		switch (n_flash_oobsize) {
		case 64:
			nandflash_ecc4();
			ecc_strength = 4;
			break;
		case 112:
			nandflash_oob112();
			ecc_strength = 8;
			break;
		case 128:
			nandflash_ecc8();
			ecc_strength = 8;
			break;
		case 256:
			nandflash_ecc16();
			ecc_strength = 16;
			break;
		default:;
		}
	}

	NAND_WRITE_REG(0x3f << 24, ECC_ENABLE_STATUS);
	NAND_WRITE_REG(page, START_ROW_ADDR);
	NAND_WRITE_REG((NAND_DMA_ENABLE << 28) | (4<<16) | (ecc_strength<<8) | (ecc_enable<<5) | (1<<4) | (0 << 1) | (0<<0), CTRL_CONFIG);
	/* enable NAND Controller */
	NAND_WRITE_REG(reg_val | 0x01, ENABLE_STATUS);
	NAND_WRITE_REG((uint32_t)buf - GX_DRAM_VIRTUAL_OFFSET, DMA_START_ADDR);
	NAND_WRITE_REG(page_size, XFER_TOTAL_SIZE);
	NAND_WRITE_REG(page, C3F_ROW_ADDR);

	do {
		reg_val = NAND_READ_REG(INT_STATUS);
	} while(!(reg_val & 0x0100));

#if NAND_DMA_ENABLE
	cache_flush_all();
#endif
	NAND_WRITE_REG(1, XFER_START);
#if NAND_DMA_ENABLE
	while(1) {
		reg_val = NAND_READ_REG(INT_STATUS);
		if (reg_val & 0x01)
			break;
		else if (reg_val & (0x01 << 20)) {
			bkpt_continue = NAND_READ_REG(BKPT_CONTINUE);
			NAND_WRITE_REG(bkpt_continue, BKPT_CONTINUE);
		}
	}
#else
	uint32_t i = 0, fifo_amount_remain;
	uint32_t *p = (uint32_t*)buf;
	while ((i*4) < page_size) {
		reg_val = NAND_READ_REG(ENABLE_STATUS);
		if (reg_val & (1<<4)) {
			fifo_amount_remain = (NAND_READ_REG(ENABLE_STATUS) >> 16) & 0x3ff;
			while (fifo_amount_remain) {
				p[i++] = NAND_READ_REG(DATA_REGISTER);
				fifo_amount_remain -= 4;
			}
		} else {
			reg_val = NAND_READ_REG(INT_STATUS);
			if (reg_val & (0x01 << 20)) {
				bkpt_continue = NAND_READ_REG(BKPT_CONTINUE);
				NAND_WRITE_REG(bkpt_continue, BKPT_CONTINUE);
				} else if (reg_val & 0x01)
					break;
			}
		}
#endif
	return 0;
#else
	uint8_t *p;
	int res;
	int ret = 0;
	volatile struct nand *nandp = (volatile struct nand *)REG_BASE_NANDFLASH;
	uint32_t *oob_data = (uint32_t *)(TEMPORARY_BUF_START_2);
	uint32_t ecctype = n_flash_eccbytes / 7 * 4;
	/* read oob */
	n_flash_read_prepare(NAND_FLASH_PAGE_SIZE, page);
	nandp->cfg_dma_ctrl |= (1<<28);
	nandp->cfg_ecc = (1<<30) | (n_flash_eccbytes<<16) | (ecctype<<10) | (1<<2) | (1<<1);
	n_flash_read_oob(oob_data);
	/* read data */
	n_flash_read_prepare(0, page);
	nandp->cfg_ecc = (1<<30) | (n_flash_eccbytes<<16) | (ecctype<<10) | (1<<1) | (1<<0);
	n_flash_read(NAND_FLASH_PAGE_SIZE/4, buf);

	if (n_flash_ecc_buildin == true)
		return 0;

	/* wait ecc done */
	while( !((nandp->status_reg1) & (0x1 << 6)));
	nandp->status_reg1 |= (0x1 << 6);

	uint32_t eccsteps = 4, i, j;
	p = (uint8_t *)buf;
	uint32_t ecc_start_offset = n_flash_oobsize - n_flash_eccbytes * 4;
	uint32_t erase_mark_offset = ecc_start_offset - 4;
	for (i = 0; eccsteps; eccsteps--, i++, p += 512) {
		if (nand_page_sector_is_erase_from_mark((uint8_t*)oob_data + erase_mark_offset, i)) {
			for (j = 0; j < 512; j++)
				p[j] = 0xFF;
		} else {
			res = ecc_correct(p, i, (uint8_t*)oob_data + ecc_start_offset + i * n_flash_eccbytes);
			if (res == -1)
				ret = -1;
		}
	}

	return ret;
#endif
}

/*
 * nand_id_has_period - Check if an ID string has a given wraparound period
 * @id_data: the ID string
 * @arrlen: the length of the @id_data array
 * @period: the period of repitition
 *
 * Check if an ID string is repeated within a given sequence of bytes at
 * specific repetition interval period (e.g., {0x20,0x01,0x7F,0x20} has a
 * period of 3). This is a helper function for nand_id_len(). Returns non-zero
 * if the repetition has a period of @period; otherwise, returns zero.
 */
static int nand_id_has_period(u8 *id_data, int arrlen, int period)
{
	int i, j;
	for (i = 0; i < period; i++)
		for (j = i + period; j < arrlen; j += period)
			if (id_data[i] != id_data[j])
				return 0;
	return 1;
}

/*
 * nand_id_len - Get the length of an ID string returned by CMD_READID
 * @id_data: the ID string
 * @arrlen: the length of the @id_data array

 * Returns the length of the ID string, according to known wraparound/trailing
 * zero patterns. If no pattern exists, returns the length of the array.
 */
static int nand_id_len(u8 *id_data, int arrlen)
{
	int last_nonzero, period;

	/* Find last non-zero byte */
	for (last_nonzero = arrlen - 1; last_nonzero >= 0; last_nonzero--)
		if (id_data[last_nonzero])
			break;

	/* All zeros */
	if (last_nonzero < 0)
		return 0;

	/* Calculate wraparound period */
	for (period = 1; period < arrlen; period++)
		if (nand_id_has_period(id_data, arrlen, period))
			break;

	/* There's a repeated pattern */
	if (period < arrlen)
		return period;

	/* There are trailing zeros */
	if (last_nonzero < arrlen - 1)
		return last_nonzero + 1;

	/* No pattern detected */
	return arrlen;
}

/*
 * assume slc nand, page size 2048.
 */
#define NAND_MFR_TOSHIBA	0x98
#define NAND_MFR_GIGADEVICE     0xC8

static int n_flash_decode_ext_id(void)
{
	int extid, id_len, oobsize, i;
	volatile struct nand *nandp = (volatile struct nand *)REG_BASE_NANDFLASH;
	uint8_t id_data[8];
	int writesize = 2048;

	n_flash_tx_cmd(nandp, NAND_FLASH_READID_CMD);
	n_flash_tx_addr(nandp, 0x00);

	for (i = 0; i < 8; i++) {
		id_data[i] = n_flash_read_byte();
	}

	/* The 4th id byte is the important one */
	extid = id_data[3];

	id_len = nand_id_len(id_data, 8);

	/* Calc pagesize */
	extid >>= 2;
	/* Calc oobsize */
	oobsize = (8 << (extid & 0x01)) *
		(writesize >> 9);
	/*
	 * Toshiba 24nm raw SLC (i.e., not BENAND) have 32B OOB per
	 * 512B page. For Toshiba SLC, we decode the 5th/6th byte as
	 * follows:
	 * - ID byte 6, bits[2:0]: 100b -> 43nm, 101b -> 32nm,
	 *                         110b -> 24nm
	 * - ID byte 5, bit[7]:    1 -> BENAND, 0 -> raw SLC
	 */
	if (id_len >= 6 && id_data[0] == NAND_MFR_TOSHIBA &&
			(id_data[5] & 0x7) == 0x6 /* 24nm */ &&
			!(id_data[4] & 0x80) /* !BENAND */) {
		oobsize = 32 * writesize >> 9;
	} else if (id_len >= 6 && id_data[0] == NAND_MFR_GIGADEVICE &&
				(id_data[1] == 0x6A)) {
			extid = id_data[3];
			extid >>= 2;
			oobsize = (16 << (extid & 0x01)) * (writesize >> 9);
		}
	return oobsize;
}

static int nand_block_isbad(uint32_t page)
{
	int res = 0;
	uint8_t *ecc_code = (uint8_t *)(TEMPORARY_BUF_START_2);
	volatile struct nand *nandp = (volatile struct nand *)REG_BASE_NANDFLASH;
	uint32_t* nand_bbt = (uint32_t*)TEMPORARY_BUF_BBT;
	uint32_t block_id, reg_val;

	block_id = page / 64;

	if (bbt_ready == true) {
		if (((nand_bbt[2+block_id/16] >> ((block_id % 16) << 1)) & 0x03)\
				!= 0x03)
			return 1;
		else
			return 0;
	}

	page = block_id * 64; //128K block,2K page

#ifdef CONFIG_ARCH_ARM_CANOPUS
	/* disable NAND Controller */
	reg_val = NAND_READ_REG(ENABLE_STATUS);
	NAND_WRITE_REG(reg_val & (~0x01), ENABLE_STATUS);
	NAND_WRITE_REG(0x00, INT_ENABLE);
	NAND_WRITE_REG(0x3f << 24, ECC_ENABLE_STATUS);

	NAND_WRITE_REG((n_flash_pagesize << 16) | (n_flash_pagesize), TYPE0_START_ADDR);
	NAND_WRITE_REG(1, TYPE0_LENGTH);
	NAND_WRITE_REG(0, TYPE0_GAP);
	NAND_WRITE_REG(0, TYPE1_LENGTH);
	NAND_WRITE_REG(0, TYPE2_LENGTH);
	NAND_WRITE_REG(0xffff, END_TYPE012_ADDR);
	NAND_WRITE_REG(0xffff, TYPE3_RELOAD_COL_ADDR);
	NAND_WRITE_REG(n_flash_pagesize, END_COL_ADDR);

	NAND_WRITE_REG(page, START_ROW_ADDR);

	NAND_WRITE_REG((0<< 28) | (4<<16) | (8<<8) | (0<<5) | (0<<4) | (0<<1), CTRL_CONFIG);

	NAND_WRITE_REG(0, BAD_BLOCK_MARK_0);
	NAND_WRITE_REG(0, BAD_BLOCK_MARK_1);
	/* enable NAND Controller */
	NAND_WRITE_REG(reg_val | 0x01, ENABLE_STATUS);
	NAND_WRITE_REG(1, XFER_TOTAL_SIZE);

	do {
		reg_val = NAND_READ_REG(INT_STATUS);
	} while(!(reg_val & 0x0100));

	NAND_WRITE_REG(1, XFER_START);

	while (1) {
		reg_val = NAND_READ_REG(ENABLE_STATUS);
		if (reg_val & (1<<4)) {
			//fifo_amount_remain = (NAND_READ_REG(ENABLE_STATUS) >> 16) & 0x3ff;
			ecc_code[0] = NAND_READ_REG(DATA_REGISTER);
			break;
		}
	}

	do {
		reg_val = NAND_READ_REG(INT_STATUS);
	} while(!(reg_val & 0x01));
#else
	/* read oob */
	n_flash_read_prepare(NAND_FLASH_PAGE_SIZE, page);
	nandp->cfg_dma_ctrl |= (1<<28);
	nandp->cfg_ecc = (1<<30) | (7<<16) | (4<<10) | (1<<2) | (1<<1);
	n_flash_read_oob((uint32_t *)ecc_code);
#endif
	if (ecc_code[0] != 0xff)
		res = 1;

	return res;
}

static int copy_from_nflash(unsigned int addr, unsigned int len, unsigned char *buf)
{
	uint32_t i = 0;
	uint32_t page_size = n_flash_pagesize;
	uint32_t page_num_per_block = 64;
	uint32_t data_len = len;
	uint32_t tmp_len = 0;
	uint32_t tmp_addr = addr;
	uint32_t page = addr / page_size;
	uint32_t page_offset = 0;
	unsigned char *tmp_buf = (unsigned char *)TEMPORARY_BUF_START_1;

	while (data_len) {
		if (page % page_num_per_block == 0) {
			if(nand_block_isbad(page)) {
				page = (page / page_num_per_block + 1) * page_num_per_block; //128K block,2K page
				continue;
			}
		}
		n_flash_do_read_page(page, (uint32_t *)tmp_buf);
		page_offset = tmp_addr % page_size;
		tmp_len = min(data_len, page_size - page_offset);
		for (i = 0; i < tmp_len; i++)
			*(buf + i) = *(tmp_buf + page_offset + i);

		page++;
		data_len -= tmp_len;
		tmp_addr += tmp_len;
		buf += tmp_len;
	}
	return len;
}
#endif

int copy_from_flash(unsigned int addr, unsigned int len, unsigned char *buf)
{
#ifdef CONFIG_ENABLE_ADAPTIVE_FLASH
	adaptive.read_flash(addr, len, buf);
#else
#if defined(CONFIG_ENABLE_SFLASH)
	copy_from_sflash(addr, len, buf);
#elif defined(CONFIG_ENABLE_SPINAND)
	copy_from_snflash(addr, len, buf);
#elif defined(CONFIG_ENABLE_NANDFLASH)
	copy_from_nflash(addr, len, buf);
#endif
#endif
	return 0;
}

