#define DW_WAIT_IDLE(base, offset, state, bit) do {\
			state = *(volatile unsigned int *)(((base) + (offset)));\
} while( ((state) & (1 << (bit))) )

static void serial_set_pin_multip(int no_mmu)
{
	volatile unsigned int pin_sel0 = 0;
	volatile unsigned int pin_sel1 = 0;
	volatile unsigned int base = 0;

	if (no_mmu)
		base = GX_REG_VIRTUAL_BASE1;
	else
		base = 0x0;

#if defined(CONFIG_ARCH_CKMMU_GX3201) || defined(CONFIG_ARCH_CKMMU_GX3113C)
	pin_sel0 = *(volatile unsigned int *)(REG_PINMUX_PORTA - base);
	pin_sel1 = *(volatile unsigned int *)(REG_PINMUX_PORTC - base);

	pin_sel0 |= (1 << 17) | (1 << 18); // Multiple pin
	pin_sel1 |= (1 << 6);

	*(volatile unsigned int *)(REG_PINMUX_PORTA - base) = pin_sel0;
	*(volatile unsigned int *)(REG_PINMUX_PORTC - base) = pin_sel1;
#elif defined(CONFIG_ARCH_CKMMU_GX3211)
	pin_sel1 = 0;
	pin_sel0 = *(volatile unsigned int *)(REG_PINMUX_PORTE - base);
	pin_sel0 |= (0x3 << 22); // Multiple pin
	*(volatile unsigned int *)(REG_PINMUX_PORTE - base) = pin_sel0;
#elif defined(CONFIG_ARCH_CKMMU_GX6605S)
	pin_sel1 = 0;
	*(volatile unsigned int *)(REG_PINMUX_PORTE - base) = pin_sel0;
	pin_sel0 |= (0x1 << 22); // Multiple pin
	*(volatile unsigned int *)(REG_PINMUX_PORTE - base) = pin_sel0;
#elif defined(CONFIG_ARCH_ARM_SIRIUS)
	*(volatile unsigned int *)(REG_PINMUX_PORTC - base) &= ~(3 << 6);
	*(volatile unsigned int *)(REG_PINMUX_PORTD - base) &= ~(1 << 20);
	*(volatile unsigned int *)(REG_PINMUX_PORTA - base) |= (1 << 22); // select dw uart 1
	*(volatile unsigned int *)(REG_PINMUX_PORTC - base) |= (3 << 1);
	*(volatile unsigned int *)(REG_PINMUX_PORTD - base) &= ~(1 << 15);
	*(volatile unsigned int *)(REG_PINMUX_PORTA - base) |= (1 << 23); // select dw uart 2
#elif defined(CONFIG_ARCH_CKMMU_TAURUS) || defined(CONFIG_ARCH_CKMMU_GEMINI)
	pin_sel0 = *(volatile unsigned int *)(REG_PINMUX_PORTF - base);
	pin_sel0 |= (0x3 << 22); // Multiple pin
	*(volatile unsigned int *)(REG_PINMUX_PORTF - base) = pin_sel0;
#elif defined(CONFIG_ARCH_CKMMU_CYGNUS)
	*(volatile unsigned int *)(REG_INTERNAL_FUNSEL - base) |= (0x3 << 0);
#endif
}

void serial_init(int no_mmu, int sys_clock)
{
	volatile unsigned int clkdiv = 0;
	volatile unsigned int _usr = 0;
	volatile unsigned int real_uartbase = 0;

	if (no_mmu)
		real_uartbase = uartbase - GX_REG_VIRTUAL_BASE1;
	else
		real_uartbase = uartbase;

	clkdiv = (sys_clock + (8 * CONFIG_UART_BAUDRATE)) / (16 * CONFIG_UART_BAUDRATE);
	serial_set_pin_multip(no_mmu);

	*(volatile unsigned int *)(real_uartbase + DSW_IER) = 0x0;
	*(volatile unsigned int *)(real_uartbase + DSW_MCR) = 0x3;

	DW_WAIT_IDLE(real_uartbase, DSW_USR, _usr, DSW_USR_BUSY);

	*(volatile unsigned int *)(real_uartbase + DSW_LCR) = 0x80;
	*(volatile unsigned int *)(real_uartbase + DSW_DLL) = (clkdiv & 0xff);
	*(volatile unsigned int *)(real_uartbase + DSW_DLH) = ((clkdiv >> 8) & 0xff);

	DW_WAIT_IDLE(real_uartbase, DSW_USR, _usr, DSW_USR_BUSY);
	*(volatile unsigned int *)(real_uartbase + DSW_LCR) = 0x03;
	*(volatile unsigned int *)(real_uartbase + DSW_FCR) = 0x01;
	*(volatile unsigned int *)(real_uartbase + DSW_DLF) = 0x00;
}

